#include <map>
#include <list>

class singleton
{
protected:
    singleton() {}
    virtual ~singleton() {}
};

typedef int control_id_t;
typedef int axis_id_t;

enum device_id_t
{
    INVALID_DEVICE_ID = -1
};

class device_axis
{
    device_id_t device;
    axis_id_t axis;
    int control_axis;
};

typedef list<device_axis> device_axis_list_t;

enum control_t
{
    CT_BOOLEAN,
    CT_RATIONAL
};

class game_control
{
    control_id_t name;
    control_t type;
    device_axis_list_t mapping;

    friend class input_mgr;
};

typedef map<control_id_t, game_control> control_map_t;

class input_mgr : public singleton
{
    void *rumble_ptr;
    void *device_map[3];
    control_map_t control_map;

public:
    void clear_mapping();
};

void input_mgr::clear_mapping()
{
  control_map_t::iterator it = control_map.begin();
  for ( ; it != control_map.end(); ++it )
    (*it).second.mapping = device_axis_list_t();
}
